\section{Compartments}

\begin{xltabular}{\linewidth}{@{}l l >{\raggedright\arraybackslash\hspace{0pt}}X l c@{}}
  \toprule
  \textbf{Symbol} & \textbf{Id} & \textbf{Name} & \textbf{Size} & \textbf{Constant} \\
  \midrule
  \endhead
  \bottomrule
  \endfoot
  $c$ & \texttt{c} & cytosol & $\mathrm{NaN}$ & $\checkmark$ \\
\end{xltabular}

\section{Species}

\begin{xltabular}{\linewidth}{@{}l l l l >{\raggedright\arraybackslash\hspace{0pt}}X@{}}
  \toprule
  \textbf{Symbol} & \textbf{Id} & \textbf{Compartment} & \textbf{Value} & \textbf{Properties} \\
  \midrule
  \endhead
  \bottomrule
  \endfoot
  $x$ & \texttt{x} & $c$ & $10$ & concentration, boundary \\
  $y$ & \texttt{y} & $c$ & $0$ & concentration \\
\end{xltabular}

\section{Parameters}

\begin{longtable}[l]{@{}l l l c@{}}
  \toprule
  \textbf{Symbol} & \textbf{Id} & \textbf{Value} & \textbf{Constant} \\
  \midrule
  \endhead
  \bottomrule
  \endfoot
  $k_{1}$ & \texttt{k1} & $1$ & $\checkmark$ \\
  $f_{1}$ & \texttt{f1} &  &  \\
  $f_{2}$ & \texttt{f2} &  &  \\
  $\mathrm{v4}_{\mathrm{x}}$ & \texttt{v4\_x} & $\mathrm{NaN}$ & $\checkmark$ \\
  $\mathrm{v4}_{\mathrm{y}}$ & \texttt{v4\_y} & $\mathrm{NaN}$ & $\checkmark$ \\
\end{longtable}

\section{Initial assignments and assignment rules}

The initial assignments set the values at $t = 0$:
\begin{align*}
  \mathrm{v4}_{\mathrm{x}} &= 2.5 \\
  \mathrm{v4}_{\mathrm{y}} &= 5
\end{align*}

The assignment rules hold at every time $t$:
\begin{align*}
  f_{1} &= 1 \cdot t \\
  f_{2} &= 2 \cdot t
\end{align*}

\section{Reactions}

\begin{xltabular}{\linewidth}{@{}l l >{\raggedright\arraybackslash\hspace{0pt}}X@{}}
  \toprule
  \textbf{Rate} & \textbf{Id} & \textbf{Equation} \\
  \midrule
  \endhead
  \bottomrule
  \endfoot
  $v_{\mathrm{v1}}$ & \texttt{v1} & $x \longrightarrow y$ \\
  $v_{\mathrm{v2}}$ & \texttt{v2} & $x \longrightarrow 2 \, y$ \\
  $v_{\mathrm{v3}}$ & \texttt{v3} & $f_{1} \, x \longrightarrow f_{2} \, y$ \\
  $v_{\mathrm{v4}}$ & \texttt{v4} & $\mathrm{v4}_{\mathrm{x}} \, x \longrightarrow \mathrm{v4}_{\mathrm{y}} \, y$ \\
\end{xltabular}

The rates of the reactions are:
\begin{align*}
  v_{\mathrm{v1}} &= k_{1} \cdot x \\
  v_{\mathrm{v2}} &= k_{1} \cdot x \\
  v_{\mathrm{v3}} &= k_{1} \cdot x \\
  v_{\mathrm{v4}} &= k_{1} \cdot x
\end{align*}

\section{ODE system}

The states change in time with the rates of the reactions:
\begin{align*}
  \frac{\mathrm{d} y}{\mathrm{d} t} &= \frac{v_{\mathrm{v1}} + 2 \cdot v_{\mathrm{v2}} + f_{2} \cdot v_{\mathrm{v3}} + \mathrm{v4}_{\mathrm{y}} \cdot v_{\mathrm{v4}}}{c}
\end{align*}

